insert into category_pages (slug, title, category_id, description) values ('cashback-credit-cards', 'Cashback Credit Cards', 'cashback', 'Cashback credit cards return a percentage of your spends as direct cashback, usually credited against your statement. They are ideal for users who prefer straightforward savings over reward points, especially on online shopping, bill payments and everyday purchases.');
insert into category_pages (slug, title, category_id, description) values ('rewards-credit-cards', 'Rewards Credit Cards', 'rewards', 'Rewards credit cards earn points on every transaction that can be redeemed for vouchers, products, air miles or statement credit. Accelerated rewards on select categories help frequent spenders extract maximum value from their cards.');
insert into category_pages (slug, title, category_id, description) values ('lifetime-free-credit-cards', 'Lifetime Free Credit Cards', 'lifetime-free', 'Lifetime free credit cards charge no joining or annual fee, ever. They are a great starting point for first-time users and a zero-cost way to enjoy basic rewards, offers and the convenience of credit.');
insert into category_pages (slug, title, category_id, description) values ('rupay-credit-cards', 'RuPay Credit Cards', 'rupay', 'RuPay credit cards run on India’s domestic card network and can be linked to UPI apps, letting you scan & pay with your credit card. Many RuPay variants also offer rewards on UPI spends along with the usual card benefits.');
insert into category_pages (slug, title, category_id, description) values ('credit-cards-lounge-access', 'Credit Cards with Lounge Access', 'lounge-access', 'These credit cards offer complimentary domestic and international airport lounge visits. Frequent flyers can relax, dine and work at premium lounges without paying per-visit charges.');
insert into category_pages (slug, title, category_id, description) values ('onecard-credit-cards', 'OneCard Credit Cards', 'onecard', 'OneCard is a mobile-first metal credit card issued in partnership with leading banks. It offers lifetime free usage, 5X rewards on your top spend categories and complete card control through the OneCard app.');
insert into category_pages (slug, title, category_id, description) values ('fuel-credit-cards', 'Fuel Credit Cards', 'fuel', 'Fuel credit cards provide fuel surcharge waivers and accelerated rewards or cashback at petrol pumps. Regular commuters can significantly cut down their monthly fuel expenses with the right co-branded fuel card.');
insert into category_pages (slug, title, category_id, description) values ('travel-credit-cards', 'Travel Credit Cards', 'travel', 'Travel credit cards earn air miles or accelerated rewards on flight and hotel bookings, offer airport lounge access, travel insurance and partner discounts — perfect companions for frequent travellers.');
insert into category_pages (slug, title, category_id, description) values ('international-credit-cards', 'International Credit Cards', 'international', 'International credit cards are accepted worldwide and are optimised for overseas usage with benefits like global lounge access, travel insurance and low foreign currency markup fees.');
insert into category_pages (slug, title, category_id, description) values ('zero-forex-markup-credit-cards', 'Zero Forex Markup Credit Cards', 'zero-forex', 'Zero forex markup credit cards waive the usual 3.5% foreign exchange fee on international transactions, making them the most economical way to spend abroad or on international websites.');
insert into category_pages (slug, title, category_id, description) values ('secured-credit-cards', 'Secured Credit Cards', 'secured', 'Secured credit cards are issued against a fixed deposit, so approval is guaranteed regardless of credit history. They are the easiest way for students, homemakers and new-to-credit users to start building a credit score.');
insert into faqs (page, question, answer, position) values ('home', 'What is a credit card?', 'A credit card is a type of credit facility, issued through a plastic or a virtual card. Consumers can use it for making transactions within their preset credit limit and repay the spent amount by the due date, which usually falls after every 30-45 days.', 0);
insert into faqs (page, question, answer, position) values ('home', 'How does a credit card work?', 'Unlike a debit card, where money is directly debited from your bank account when you make a payment, in the case of a credit card, the money is deducted from the assigned credit limit. In a way, you borrow funds from the issuer to make a payment. Based on the total funds used within a month (statement cycle), the issuer then sends a card statement to the user with the total amount due on the card.', 1);
insert into faqs (page, question, answer, position) values ('home', 'What are the benefits of having a credit card?', 'Some benefits of owning a credit card are increased purchasing power, financial aid in case of emergency, complimentary benefits, rewards, cashback, and lifestyle benefits. Additionally, if used wisely and responsibly, a credit card can also help in improving or building credit score.', 2);
insert into faqs (page, question, answer, position) values ('home', 'What is a credit limit and how is it determined?', 'A credit limit is the total spend capacity issued on your credit card. It is decided by the issuer based on various factors like credit score, credit history, employment type, monthly salary, and existing financial obligations.', 3);
insert into faqs (page, question, answer, position) values ('home', 'What is the APR Rate?', 'APR (Annual Percentage Rate) is the annual interest charged on an unpaid balance on a credit card. This interest rate is calculated including the nominal interest rate plus any fees or additional costs associated with the credit card.', 4);
insert into faqs (page, question, answer, position) values ('home', 'How to transfer money from credit card to bank account?', 'You can transfer money from a credit card to a bank account through various ways, such as net banking or mobile wallets. However, it is not advisable to do so regularly as it attracts cash advance fees and interest from day one.', 5);
insert into faqs (page, question, answer, position) values ('home', 'What is the minimum due amount on a credit card?', 'The minimum due is the minimum amount you have to pay on your credit card bill to avoid late payment fees. This is typically a small percentage of your total outstanding balance, usually around 5% of the total amount due.', 6);
insert into faqs (page, question, answer, position) values ('home', 'Can I get a loan against my credit card?', 'Yes, some credit cards offer a loan facility against your available credit limit, known as a credit card loan. This loan typically has a fixed interest rate and tenure, offering a convenient way to borrow without additional documentation.', 7);
insert into faqs (page, question, answer, position) values ('home', 'How can I increase my credit score with a credit card?', 'Improving your credit score with a credit card requires responsible usage. To build a strong credit score, always pay your credit card bills on time and in full, keep your credit utilization below 30%, and avoid multiple credit card applications in a short period.', 8);
insert into faqs (page, question, answer, position) values ('home', 'How to increase my credit card limit?', 'To increase your credit card limit, contact your card issuer and request a credit limit increase. However, the approval depends on your spending pattern, repayment history, credit score, and income. Regular and responsible card usage often leads to automatic limit increases.', 9);
insert into faqs (page, question, answer, position) values ('home', 'Can a cardholder with an existing credit card apply for another one?', 'Yes, most card issuers allow individuals to have multiple credit cards. However, policies vary between issuers. Before applying for a second credit card, ensure you have a good credit score and can manage multiple card payments responsibly.', 10);
insert into faqs (page, question, answer, position) values ('home', 'How to upgrade your credit card?', 'If you want to upgrade your existing credit card, you can contact your card issuer and request an upgrade. However, the approval depends on your eligibility, spending pattern, and credit history. Some issuers also offer automatic upgrades based on your card usage.', 11);
insert into faqs (page, question, answer, position) values ('home', 'Can I use my credit card outside India? What are the charges?', 'Yes, most credit cards can be used for domestic as well as international transactions. However, a foreign exchange markup fee of around 3.5% is usually charged on international transactions. Some premium cards offer zero or lower forex markup.', 12);
insert into faqs (page, question, answer, position) values ('home', 'Is it safe to save my credit card details on websites?', 'It is generally not recommended to save your credit card details on websites due to the risk of data breaches and fraud. However, with tokenisation, where actual card details are replaced with unique tokens, the security of saved card information has improved significantly.', 13);
insert into faqs (page, question, answer, position) values ('interest-rates', 'What is the interest rate on a credit card?', 'Credit card interest rate, usually expressed as monthly interest rate or Annual Percentage Rate (APR), is the rate charged on the outstanding balance when the total due amount is not paid by the due date. In India it typically ranges from 1.99% to 3.75% per month (23.88% to 45% annually).', 14);
insert into faqs (page, question, answer, position) values ('interest-rates', 'When is credit card interest charged?', 'Interest is charged when you do not pay the total amount due by the due date, withdraw cash using your credit card, or convert purchases into EMIs. No interest is charged if you pay the total outstanding in full every billing cycle.', 15);
insert into faqs (page, question, answer, position) values ('interest-rates', 'How can I avoid paying interest on my credit card?', 'Always pay the total amount due (not just the minimum due) on or before the due date. Utilise the interest-free period of 20-50 days, avoid cash withdrawals on the credit card and set up auto-debit so you never miss a payment.', 16);
insert into faqs (page, question, answer, position) values ('interest-rates', 'Is interest charged on the minimum amount due?', 'If you only pay the minimum amount due, interest is charged on the remaining outstanding balance and on fresh transactions from the transaction date. Paying only the minimum due can quickly build up a large debt.', 17);
insert into faqs (page, question, answer, position) values ('cibil-score', 'What CIBIL score is required for a credit card?', 'Most issuers prefer a CIBIL score of 700 or above for unsecured credit cards. Premium cards may need 750+. Applicants with lower scores can consider secured (FD-backed) credit cards that do not require a credit history.', 18);
insert into faqs (page, question, answer, position) values ('cibil-score', 'Can I get a credit card with no credit history?', 'Yes. If you are new to credit, you can start with a secured credit card issued against a fixed deposit, or entry-level cards offered to salaried professionals. Responsible usage will help you build your credit score.', 19);
insert into faqs (page, question, answer, position) values ('cibil-score', 'Does applying for a credit card affect my CIBIL score?', 'Every direct application triggers a hard enquiry, which may temporarily reduce your score by a few points. Checking pre-approved offers on Book My Credit Card involves a soft enquiry and does not impact your score.', 20);
insert into faqs (page, question, answer, position) values ('cibil-score', 'How can I improve my CIBIL score using a credit card?', 'Pay bills on time and in full, keep credit utilisation under 30%, avoid multiple applications in a short span, and keep old cards active. Consistent, responsible usage steadily improves your score.', 21);
insert into faqs (page, question, answer, position) values ('eligibility', 'What is the minimum income required for a credit card?', 'Income requirements differ by card. Entry-level cards may be available at a monthly income of ₹15,000-₹20,000, while premium cards can require ₹1 lakh or more per month. Secured cards have no income requirement.', 22);
insert into faqs (page, question, answer, position) values ('eligibility', 'What is the minimum age for a credit card?', 'The primary cardholder must usually be at least 18 years old (21 for many issuers). The maximum age is generally 60-65 years. Add-on cards can often be issued to family members aged 18 and above.', 23);
insert into faqs (page, question, answer, position) values ('eligibility', 'Which documents are required for a credit card application?', 'You typically need identity proof (PAN, Aadhaar, passport), address proof (Aadhaar, utility bill, passport), income proof (salary slips, Form 16, ITR or bank statements) and a passport-size photograph.', 24);
insert into faqs (page, question, answer, position) values ('eligibility', 'Can self-employed individuals get a credit card?', 'Yes. Self-employed applicants can get credit cards by submitting income proof such as ITR or audited financials. Issuers may also consider banking relationships and business vintage.', 25);
