insert into page_sections (page, title, body, position) values ('cibil-score', 'Why your CIBIL score matters for a credit card', 'Your CIBIL score is a 3-digit number between 300 and 900 that summarises your credit history. Card issuers use it as the first filter while evaluating applications — a higher score signals disciplined repayment behaviour and improves both your approval chances and the credit limit offered.', 0);
insert into page_sections (page, title, body, position) values ('cibil-score', 'Ideal CIBIL score for credit card approval', 'A score of 750 and above is considered excellent and qualifies you for most premium credit cards. Scores between 700-749 are good and eligible for a wide range of cards. Between 650-699 approval is possible but options shrink, and below 650 you should consider a secured card and rebuild your score first.', 1);
insert into page_sections (page, title, body, position) values ('cibil-score', 'How to check your CIBIL score for free', 'You can check your latest CIBIL score for free on Book My Credit Card. Checking your own score is a soft enquiry and never impacts the score. You also get a detailed credit report highlighting the accounts and payment history that drive your score.', 2);
insert into page_sections (page, title, body, position) values ('cibil-score', 'Improving a low credit score', 'Pay every EMI and credit card bill on time, keep total credit utilisation under 30%, avoid applying to multiple lenders in a short window, retain your oldest credit lines and periodically review your credit report for reporting errors and raise disputes where needed.', 3);
